function renderResources(subject){
 const box=$(`${subject}Resources`),items=resources.filter(r=>r.subject===subject);box.innerHTML=items.map(r=>`<div class="resource-item"><div><b>${escapeHtml(r.name)}</b><span>${escapeHtml(r.url)}</span></div><a href="${escapeAttr(r.url)}" target="_blank" rel="noopener">打开</a><button data-delete-resource="${r.id}">删除</button></div>`).join('')+(items.length?'':'<div class="empty">尚未添加课程链接。</div>');box.querySelectorAll('[data-delete-resource]').forEach(b=>b.onclick=()=>{resources=resources.filter(r=>r.id!==b.dataset.deleteResource);write('tri-resources',resources);renderResources(subject)})
}
document.querySelectorAll('[data-add-resource]').forEach(b=>b.onclick=()=>{const subject=b.dataset.addResource,name=$(`${subject}ResourceName`).value.trim(),url=$(`${subject}ResourceUrl`).value.trim();if(!name||!/^https?:\/\//i.test(url))return toast('请填写名称和以 http 开头的合法链接');resources.push({id:uid(),subject,name,url});write('tri-resources',resources);$(`${subject}ResourceName`).value='';$(`${subject}ResourceUrl`).value='';renderResources(subject);toast('资源链接已保存')});

function openFileDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('tri-study-files',3);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('files'))req.result.createObjectStore('files',{keyPath:'id'});if(!req.result.objectStoreNames.contains('handles'))req.result.createObjectStore('handles',{keyPath:'id'});if(!req.result.objectStoreNames.contains('ink'))req.result.createObjectStore('ink',{keyPath:'id'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function storeStudyFile(subject,file){const db=await openFileDb();await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put({id:uid(),subject,name:file.name,type:file.type,blob:file,created:Date.now()});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
async function listStudyFiles(subject){const db=await openFileDb(),all=await new Promise((resolve,reject)=>{const req=db.transaction('files').objectStore('files').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});db.close();return all.filter(x=>x.subject===subject)}
async function deleteStudyFile(id){const db=await openFileDb();await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
async function renderStoredFiles(subject){try{const box=$(`${subject}Resources`),files=await listStudyFiles(subject);files.forEach(f=>{const el=document.createElement('div');el.className='resource-item';el.innerHTML=`<div><b>${escapeHtml(f.name)}</b><span>保存在当前浏览器 · 本地讲义</span></div><button data-open>打开</button><button data-del>删除</button>`;el.querySelector('[data-open]').onclick=()=>{const url=URL.createObjectURL(f.blob);window.open(url,'_blank');setTimeout(()=>URL.revokeObjectURL(url),60000)};el.querySelector('[data-del]').onclick=async()=>{await deleteStudyFile(f.id);renderResources(subject);renderStoredFiles(subject)};box.appendChild(el)})}catch{}}
['math','politics'].forEach(subject=>{$(`${subject}File`).onchange=async e=>{const file=e.target.files[0];if(!file)return;try{await storeStudyFile(subject,file);renderResources(subject);await renderStoredFiles(subject);toast('本地讲义已保存')}catch{toast('文件保存失败，可能超过浏览器容量限制')}}});
async function getInkRecord(id){const db=await openFileDb(),row=await new Promise((resolve,reject)=>{const req=db.transaction('ink').objectStore('ink').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});db.close();return row}
async function saveInk(subject){const state=inkState[subject];if(!state.key)return;try{const db=await openFileDb();await new Promise((resolve,reject)=>{const tx=db.transaction('ink','readwrite');tx.objectStore('ink').put({id:state.key,strokes:state.strokes,updated:Date.now()});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}catch{toast('手写笔记保存失败') }}
function inkCanvas(subject){return $(`${subject}Ink`)}
function resizeInk(subject){const canvas=inkCanvas(subject),rect=canvas.getBoundingClientRect();if(rect.width<10)return false;const ratio=Math.max(1,window.devicePixelRatio||1),w=Math.round(rect.width*ratio),h=Math.round(rect.height*ratio);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}return true}
function redrawInk(subject){const canvas=inkCanvas(subject);if(!resizeInk(subject))return;const ctx=canvas.getContext('2d'),ratio=Math.max(1,window.devicePixelRatio||1),w=canvas.width/ratio,h=canvas.height/ratio;ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,w,h);for(const stroke of inkState[subject].strokes){if(stroke.points.length<1)continue;ctx.save();ctx.globalCompositeOperation=stroke.tool==='eraser'?'destination-out':'source-over';ctx.strokeStyle=stroke.color;ctx.lineWidth=stroke.tool==='eraser'?stroke.width*4:stroke.width;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();stroke.points.forEach((p,i)=>{const x=p.x*w,y=p.y*h;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});if(stroke.points.length===1)ctx.lineTo(stroke.points[0].x*w+.1,stroke.points[0].y*h+.1);ctx.stroke();ctx.restore()}}
function bindInk(subject){const canvas=inkCanvas(subject),state=inkState[subject];if(canvas.dataset.inkBound)return;canvas.dataset.inkBound='1';const point=e=>{const r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height)),pressure:e.pressure||.5}};canvas.onpointerdown=e=>{e.preventDefault();canvas.setPointerCapture?.(e.pointerId);state.active={tool:state.tool,color:state.color,width:state.width,points:[point(e)]};state.strokes.push(state.active);redrawInk(subject)};canvas.onpointermove=e=>{if(!state.active)return;e.preventDefault();state.active.points.push(point(e));redrawInk(subject)};const finish=()=>{if(!state.active)return;state.active=null;saveInk(subject)};canvas.onpointerup=finish;canvas.onpointercancel=finish;canvas.onpointerleave=e=>{if(e.buttons===0)finish()}}
async function loadInk(subject){const canvas=inkCanvas(subject);if(!resizeInk(subject))return;bindInk(subject);const key=`${subject}-${dateKey(selectedPlanDate)}`,state=inkState[subject];if(state.key!==key){state.key=key;try{state.strokes=(await getInkRecord(key))?.strokes||[]}catch{state.strokes=[]}}redrawInk(subject)}
document.querySelectorAll('[data-ink-tool]').forEach(b=>b.onclick=()=>{const subject=b.dataset.inkSubject;inkState[subject].tool=b.dataset.inkTool;document.querySelectorAll(`[data-ink-tool][data-ink-subject="${subject}"]`).forEach(x=>x.classList.toggle('active',x===b))});document.querySelectorAll('[data-ink-color]').forEach(x=>x.oninput=()=>{inkState[x.dataset.inkColor].color=x.value;inkState[x.dataset.inkColor].tool='pen'});document.querySelectorAll('[data-ink-width]').forEach(x=>x.oninput=()=>inkState[x.dataset.inkWidth].width=+x.value);document.querySelectorAll('[data-ink-undo]').forEach(b=>b.onclick=()=>{const s=b.dataset.inkUndo;inkState[s].strokes.pop();redrawInk(s);saveInk(s)});document.querySelectorAll('[data-ink-clear]').forEach(b=>b.onclick=()=>{const s=b.dataset.inkClear;if(confirm('清空当天这块手写板吗？')){inkState[s].strokes=[];redrawInk(s);saveInk(s)}});document.querySelectorAll('[data-ink-export]').forEach(b=>b.onclick=()=>{const s=b.dataset.inkExport,canvas=inkCanvas(s),out=document.createElement('canvas');out.width=canvas.width;out.height=canvas.height;const ctx=out.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,out.width,out.height);ctx.drawImage(canvas,0,0);const a=document.createElement('a');a.href=out.toDataURL('image/png');a.download=`${s}-${dateKey(selectedPlanDate)}-notes.png`;a.click()});window.addEventListener('resize',()=>['english','math','politics'].forEach(redrawInk));
document.querySelectorAll('[data-ink-toggle]').forEach(button=>button.onclick=()=>{const subject=button.dataset.inkToggle,state=inkState[subject];state.enabled=!state.enabled;if(subject==='english')$('readingAnnotator').classList.toggle('ink-active',state.enabled);button.classList.toggle('primary',!state.enabled);button.classList.toggle('soft',state.enabled);button.textContent=state.enabled?'退出批注，恢复滚动':'开启批注';if(state.enabled)toast('批注模式已开启，可直接在原文上圈画')});

async function allInkRecords(){const db=await openFileDb(),rows=await new Promise((resolve,reject)=>{const req=db.transaction('ink').objectStore('ink').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});db.close();return rows}
function syncLocalRecords(){const values={};for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key?.startsWith('tri-'))values[key]=localStorage.getItem(key)}return values}
async function buildSyncBundle(){return{kind:'sanxian-progress-room-sync',version:1,exportedAt:new Date().toISOString(),source:location.host||'local-file',localStorage:syncLocalRecords(),ink:await allInkRecords()}}
function downloadSyncFile(file){const a=document.createElement('a');a.href=URL.createObjectURL(file);a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),30000)}
async function exportSyncBundle(){try{$('syncState').textContent='正在整理数据…';const bundle=await buildSyncBundle(),file=new File([JSON.stringify(bundle)],`三线进度室-同步包-${dateKey()}.json`,{type:'application/json'});localStorage.setItem('tri-last-sync-export',bundle.exportedAt);if(navigator.share&&navigator.canShare?.({files:[file]})){try{await navigator.share({title:'三线进度室同步包',text:'在另一台设备的同步中心导入此文件。',files:[file]})}catch(err){if(err.name!=='AbortError')downloadSyncFile(file)}}else downloadSyncFile(file);$('syncState').textContent='同步包已生成';renderSyncMeta();toast('同步包已生成，请在另一设备导入')}catch{$('syncState').textContent='生成失败';toast('同步包生成失败，请稍后重试')}}
async function importSyncBundle(file){if(!file)return;try{const bundle=JSON.parse(await file.text());if(bundle.kind!=='sanxian-progress-room-sync'||!bundle.localStorage||!Array.isArray(bundle.ink))throw new Error('invalid');if(!confirm(`将导入 ${Object.keys(bundle.localStorage).length} 组记录和 ${bundle.ink.length} 份手写笔迹，并覆盖同名数据。继续吗？`))return;Object.entries(bundle.localStorage).forEach(([key,value])=>{if(key.startsWith('tri-'))localStorage.setItem(key,value)});const db=await openFileDb();await new Promise((resolve,reject)=>{const tx=db.transaction('ink','readwrite'),store=tx.objectStore('ink');bundle.ink.forEach(row=>store.put(row));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close();localStorage.setItem('tri-last-sync-import',new Date().toISOString());toast('导入完成，正在刷新');setTimeout(()=>location.reload(),700)}catch{toast('无法导入：这不是有效的三线进度室同步包')}finally{$('importSync').value=''}}
async function renderSyncMeta(){const lastExport=localStorage.getItem('tri-last-sync-export'),lastImport=localStorage.getItem('tri-last-sync-import'),ink=await allInkRecords().catch(()=>[]),records=Object.keys(syncLocalRecords()).length,format=value=>value?new Date(value).toLocaleString('zh-CN'):'尚无';$('syncMeta').textContent=`当前设备：${records} 组记录 · ${ink.length} 份手写笔迹｜最近导出：${format(lastExport)}｜最近导入：${format(lastImport)}`}
function openSyncDialog(){$('syncState').textContent='本地安全保存';renderSyncMeta();$('syncDialog').showModal()}
$('openSync').onclick=openSyncDialog;document.querySelectorAll('[data-open-sync]').forEach(b=>b.onclick=()=>{$('mobileMoreDialog')?.close();openSyncDialog()});$('closeSync').onclick=()=>$('syncDialog').close();$('exportSync').onclick=exportSyncBundle;$('importSync').onchange=e=>importSyncBundle(e.target.files[0]);

function renderSchedule(){
 viewWeekNumber=Math.max(1,Math.min(+settings.termWeeks||30,viewWeekNumber));$('viewWeek').textContent=`第 ${viewWeekNumber} 周`;
 const periods=+settings.periodCount||12, cols=8; let html=`<div class="tt-head" style="grid-column:1;grid-row:1">节次</div>`;
 DAY_ORDER.forEach((d,i)=>html+=`<div class="tt-head" style="grid-column:${i+2};grid-row:1">${DAYS[d]}</div>`);
 for(let p=1;p<=periods;p++){html+=`<div class="tt-time" style="grid-column:1;grid-row:${p+1}">第 ${p} 节</div>`;DAY_ORDER.forEach((d,i)=>html+=`<div class="tt-cell" style="grid-column:${i+2};grid-row:${p+1}"></div>`)}
 courses.filter(c=>isActive(c,viewWeekNumber)).forEach(c=>{const col=DAY_ORDER.indexOf(+c.day)+2,span=Math.max(1,+c.end-+c.start+1);html+=`<div class="course-block ${c.type}" data-id="${c.id}" style="grid-column:${col};grid-row:${+c.start+1};height:${span*52-6}px;z-index:3"><b>${escapeHtml(c.name)}</b><span>${c.start}-${c.end}节 · ${escapeHtml(c.place||'')}</span></div>`});
 const tt=$('timetable');tt.style.gridTemplateColumns=`70px repeat(7,minmax(112px,1fr))`;tt.style.gridTemplateRows=`42px repeat(${periods},52px)`;tt.innerHTML=html;document.querySelectorAll('.course-block').forEach(el=>el.onclick=()=>openCourse(el.dataset.id));
}
$('prevWeek').onclick=()=>{viewWeekNumber--;renderSchedule()};$('nextWeek').onclick=()=>{viewWeekNumber++;renderSchedule()};
function openCourse(id=''){
 const c=courses.find(x=>x.id===id);$('courseForm').reset();$('courseId').value=c?.id||'';$('courseDialogTitle').textContent=c?'编辑课程':'添加课程';$('deleteCourse').classList.toggle('hidden',!c);
 $('courseName').value=c?.name||'';$('courseDay').value=c?.day??1;$('courseType').value=c?.type||'normal';$('startPeriod').value=c?.start||1;$('endPeriod').value=c?.end||2;$('courseWeeks').value=c?.weeks||`1-${settings.termWeeks||18}`;$('coursePlace').value=c?.place||'';$('courseDialog').showModal();
}
$('addCourseBtn').onclick=()=>openCourse();
$('courseForm').onsubmit=e=>{e.preventDefault();const start=+$('startPeriod').value,end=+$('endPeriod').value,weeks=$('courseWeeks').value.trim();if(end<start||!parseWeeks(weeks).length){toast('请检查节次或周次格式');return}const obj={id:$('courseId').value||uid(),name:$('courseName').value.trim(),day:+$('courseDay').value,type:$('courseType').value,start,end,weeks,place:$('coursePlace').value.trim()};courses=courses.filter(c=>c.id!==obj.id);courses.push(obj);write('tri-courses',courses);$('courseDialog').close();renderAll();toast('课程已保存')};
$('deleteCourse').onclick=()=>{const id=$('courseId').value;if(confirm('确定删除这门课程吗？')){courses=courses.filter(c=>c.id!==id);write('tri-courses',courses);$('courseDialog').close();renderAll();toast('课程已删除')}};
$('termBtn').onclick=()=>{$('termName').value=settings.termName||'';$('termStart').value=settings.termStart||'';$('termWeeks').value=settings.termWeeks||18;$('periodCount').value=settings.periodCount||12;$('termDialog').showModal()};
$('termForm').onsubmit=e=>{e.preventDefault();settings={termName:$('termName').value.trim(),termStart:$('termStart').value,termWeeks:+$('termWeeks').value,periodCount:+$('periodCount').value};write('tri-settings',settings);viewWeekNumber=getCurrentWeek()||1;$('termDialog').close();renderAll();toast('学期设置已更新')};

function loadPdfJs(){
 return new Promise((resolve,reject)=>{if(window.pdfjsLib)return resolve(window.pdfjsLib);const s=document.createElement('script');s.src='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';s.onload=()=>{pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';resolve(pdfjsLib)};s.onerror=()=>reject(new Error('PDF 识别组件加载失败，请检查网络后重试'));document.head.appendChild(s)});
}
$('pdfBtn').onclick=()=>{$('pdfStatus').textContent='';$('pdfCandidates').innerHTML='';$('pdfTextBox').classList.add('hidden');$('pdfTextPreview').value='';$('importCandidates').classList.add('hidden');$('pdfDialog').showModal()};$('closePdf').onclick=$('cancelPdf').onclick=()=>$('pdfDialog').close();
$('pdfInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;$('pdfStatus').textContent='正在读取 PDF…';try{const lib=await loadPdfJs(),data=await file.arrayBuffer(),pdf=await lib.getDocument({data}).promise;let lines=[];for(let p=1;p<=pdf.numPages;p++){const page=await pdf.getPage(p),content=await page.getTextContent(),groups={};content.items.forEach(it=>{const y=Math.round(it.transform[5]/3)*3;(groups[y]||(groups[y]=[])).push({x:it.transform[4],s:it.str})});Object.keys(groups).sort((a,b)=>b-a).forEach(y=>lines.push(groups[y].sort((a,b)=>a.x-b.x).map(x=>x.s).join(' ').replace(/\s+/g,' ').trim()))}pdfDrafts=parsePdfLines(lines);$('pdfTextPreview').value=lines.filter(Boolean).join('\n');$('pdfTextBox').classList.remove('hidden');renderPdfCandidates(lines.length);$('pdfStatus').textContent=`已读取 ${pdf.numPages} 页、${lines.length} 行文字，找到 ${pdfDrafts.length} 条候选课程。`;if(!pdfDrafts.length)$('pdfStatus').innerHTML+=' 当前 PDF 可能是扫描图片或特殊表格，可展开提取文字并整理后重新解析。'}catch(err){$('pdfStatus').textContent=`${err.message}。你仍可使用手动添加课程。`}};
function parsePdfLines(lines){
 const dayMap={'一':1,'二':2,'三':3,'四':4,'五':5,'六':6,'日':0,'天':0},out=[];
 lines.forEach(line=>{if(!/(周|星期)[一二三四五六日天]/.test(line)||!/(节|课)/.test(line))return;const dayChar=(line.match(/(?:周|星期)([一二三四五六日天])/)||[])[1];if(!dayChar)return;const week=(line.match(/(?:第)?([0-9，、,\-—~至 ]{1,24})周/)||[])[1]?.replace(/[，、 ]/g,',').replace(/[—~至]/g,'-')||`1-${settings.termWeeks||18}`;const per=line.match(/第?\s*(\d+)\s*(?:[-—~至]\s*(\d+))?\s*节/);let name=line.replace(/(?:周|星期)[一二三四五六日天]/g,' ').replace(/(?:第)?[0-9，、,\-—~至 ]+周/g,' ').replace(/第?\s*\d+\s*(?:[-—~至]\s*\d+)?\s*节/g,' ').replace(/[|｜()（）\[\]]/g,' ').replace(/\s+/g,' ').trim();name=name.split(/教师|地点|教室/)[0].trim();if(name.length>2)out.push({id:uid(),name:name.slice(0,40),day:dayMap[dayChar],weeks:week,start:+(per?.[1]||1),end:+(per?.[2]||per?.[1]||2),type:'normal',place:''})});
 return out.filter((x,i,a)=>a.findIndex(y=>y.name===x.name&&y.day===x.day&&y.start===x.start)===i).slice(0,50);
}
$('parsePdfText').onclick=()=>{pdfDrafts=parsePdfLines($('pdfTextPreview').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean));renderPdfCandidates();$('pdfStatus').textContent=`重新解析完成，找到 ${pdfDrafts.length} 条候选课程。`;if(!pdfDrafts.length)toast('请按示例格式整理，每门课程一行')};
function renderPdfCandidates(lineCount){
 $('pdfCandidates').innerHTML=pdfDrafts.map((c,i)=>`<div class="candidate"><input type="checkbox" class="candidate-check" data-i="${i}" checked><label>课程名<input class="candidate-name" data-i="${i}" value="${escapeAttr(c.name)}"></label><label>星期<select class="candidate-day" data-i="${i}">${DAY_ORDER.map(d=>`<option value="${d}" ${d===c.day?'selected':''}>${DAYS[d]}</option>`).join('')}</select></label><label>周次<input class="candidate-weeks" data-i="${i}" value="${escapeAttr(c.weeks)}"></label><label>节次<input class="candidate-period" data-i="${i}" value="${c.start}-${c.end}"></label></div>`).join('');$('importCandidates').classList.toggle('hidden',!pdfDrafts.length);
}
$('importCandidates').onclick=()=>{const selected=[];document.querySelectorAll('.candidate-check:checked').forEach(box=>{const i=+box.dataset.i,c={...pdfDrafts[i]};c.name=document.querySelector(`.candidate-name[data-i="${i}"]`).value.trim();c.day=+document.querySelector(`.candidate-day[data-i="${i}"]`).value;c.weeks=document.querySelector(`.candidate-weeks[data-i="${i}"]`).value.trim();const p=document.querySelector(`.candidate-period[data-i="${i}"]`).value.match(/(\d+)\D+(\d+)/);if(p){c.start=+p[1];c.end=+p[2]}if(c.name&&parseWeeks(c.weeks).length)selected.push(c)});courses.push(...selected);write('tri-courses',courses);$('pdfDialog').close();renderAll();toast(`已导入 ${selected.length} 门课程`)};

function dueQueue(){const today=dateKey(),due=deck.filter(w=>w.status!=='new'&&(!w.due||w.due<=today)),fresh=deck.filter(w=>w.status==='new').slice(0,15);return [...due,...fresh]}
function renderEnglishStats(){$('wordDue').textContent=deck.filter(w=>w.status!=='new'&&w.due<=dateKey()).length;$('deckStat').textContent=`已学 ${deck.filter(w=>w.status!=='new').length} / ${deck.length}`}
function startWordSession(){wordQueue=dueQueue();wordIndex=0;if(!wordQueue.length){$('cardLabel').textContent='今日完成';$('wordText').textContent='Great work!';$('phonetic').textContent='没有到期词，明天再来';$('revealWord').classList.add('hidden');$('wordActions').classList.add('hidden');return}showWord()}
function showWord(){currentWord=wordQueue[wordIndex];if(!currentWord){startWordSession();return}$('cardLabel').textContent=`今日 ${wordIndex+1} / ${wordQueue.length}`;$('wordText').textContent=currentWord.word;$('phonetic').textContent=currentWord.phonetic||'';$('meaning').textContent=currentWord.meaning;$('example').textContent=currentWord.example||'';$('meaning').classList.add('hidden');$('example').classList.add('hidden');$('wordActions').classList.add('hidden');$('revealWord').classList.remove('hidden');$('revealWord').textContent='显示释义'}
function revealWord(){$('meaning').classList.remove('hidden');$('example').classList.toggle('hidden',!currentWord?.example);$('wordActions').classList.remove('hidden');$('revealWord').classList.add('hidden')}
$('startWords').onclick=startWordSession;$('revealWord').onclick=e=>{e.stopPropagation();revealWord()};$('wordCard').onclick=e=>{if(currentWord&&e.target.id!=='revealWord')revealWord()};
document.querySelectorAll('.word-actions button').forEach(b=>b.onclick=()=>{if(!currentWord)return;const score=+b.dataset.score,days=[1,3,7][score],due=new Date();due.setDate(due.getDate()+days);const i=deck.findIndex(w=>w.id===currentWord.id);deck[i]={...deck[i],status:'learning',due:dateKey(due),reps:(deck[i].reps||0)+1};write('tri-word-deck',deck);wordIndex++;if(wordIndex>=wordQueue.length){wordQueue=[];$('cardLabel').textContent='今日完成';$('wordText').textContent='Well done';$('phonetic').textContent='复习记录已保存';$('meaning').classList.add('hidden');$('example').classList.add('hidden');$('wordActions').classList.add('hidden');$('revealWord').classList.add('hidden');toast('今日单词完成')}else showWord();renderEnglishStats();renderToday()});
$('addWordBtn').onclick=()=>$('wordDialog').showModal();$('wordForm').onsubmit=e=>{e.preventDefault();deck.push({id:uid(),word:$('newWord').value.trim(),phonetic:$('newPhonetic').value.trim(),meaning:$('newMeaning').value.trim(),example:$('newExample').value.trim(),status:'new',due:'',reps:0});write('tri-word-deck',deck);$('wordForm').reset();$('wordDialog').close();renderEnglishStats();toast('已加入个人词库')};
let timerSeconds=1500,timerId=null;function renderTimer(){const m=Math.floor(timerSeconds/60),s=timerSeconds%60;$('timer').textContent=`${pad(m)}:${pad(s)}`}
$('timerBtn').onclick=()=>{if(timerId){clearInterval(timerId);timerId=null;$('timerBtn').textContent='继续'}else{timerId=setInterval(()=>{timerSeconds--;renderTimer();if(timerSeconds<=0){clearInterval(timerId);timerId=null;$('timerBtn').textContent='开始';toast('专注 25 分钟完成') }},1000);$('timerBtn').textContent='暂停'}};$('timerReset').onclick=()=>{clearInterval(timerId);timerId=null;timerSeconds=1500;renderTimer();$('timerBtn').textContent='开始'};
function loadSentenceNotes(){const key=dateKey(selectedPlanDate),daily=englishFor(planIndex());$('sentenceOriginal').value=localStorage.getItem(`tri-sentenceOriginal-${key}`)||daily.long;['sentenceCore','sentenceClause','sentenceTranslation'].forEach(id=>{$(id).value=localStorage.getItem(`tri-${id}-${key}`)||''})}
['sentenceOriginal','sentenceCore','sentenceClause','sentenceTranslation'].forEach(id=>{$(id).oninput=()=>localStorage.setItem(`tri-${id}-${dateKey(selectedPlanDate)}`,$(id).value)});

function renderRoad(i=0){$('road').innerHTML=phases[i].map((x,j)=>`<article class="road-card"><div class="num">0${j+1}</div><h3>${x.name}</h3><div class="muted">${x.goal}</div><ul>${x.items.map(v=>`<li>${v}</li>`).join('')}</ul></article>`).join('')}
document.querySelectorAll('.phase').forEach(b=>b.onclick=()=>{document.querySelectorAll('.phase').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderRoad(+b.dataset.phase)});
function renderHistory(){const logs=read('tri-logs',[]);$('history').innerHTML=logs.length?`<div class="history-row"><b>日期</b><b>均重</b><b>学习</b><b>训练</b><b>引体</b><b>单词</b></div>`+logs.slice().reverse().map(x=>`<div class="history-row"><span>${x.date}</span><span>${x.weight||'—'}kg</span><span>${x.hours||'—'}h</span><span>${x.workouts||'—'}次</span><span>${x.pullups||'—'}次</span><span>${x.words||'—'}个</span></div>`).join(''):`<div class="empty">还没有记录，建议每周日更新一次。</div>`}
$('saveLog').onclick=()=>{if(!$('logDate').value)return toast('请先选择日期');let logs=read('tri-logs',[]),obj={date:$('logDate').value,weight:$('weight').value,hours:$('hours').value,workouts:$('workouts').value,pullups:$('pullups').value,words:$('wordsLearned').value};logs=logs.filter(x=>x.date!==obj.date);logs.push(obj);logs.sort((a,b)=>a.date.localeCompare(b.date));write('tri-logs',logs);renderHistory();toast('周记录已保存')};
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function escapeAttr(s=''){return escapeHtml(s)}
function renderAll(){renderHeader();renderToday();renderSchedule();render365();renderEnglish();renderMath();renderPolitics();renderFitness();renderNutrition();renderFinance();renderHistory()}
// 只提供同一套普通网页界面；清理旧安装版注册，避免手机继续读取过期缓存。
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.getRegistrations().then(items=>items.forEach(item=>item.unregister())).catch(()=>{});
$('logDate').value=dateKey();renderRoad();renderTimer();renderAll();const initialView=location.hash.slice(1);if(initialView&&VIEW_META[initialView])commitNavigation(initialView);history.replaceState({view:initialView||'today'},'',location.href);
